`timescale 1ns/1ps
// -----------------------------------------------------------------------------
// tb_comm_v2_codec -- self-checking unit test for the v2 codec.
//
// The RX stimulus is generated by an independent SLIP/CRC encoder in this
// testbench. TX bytes are decoded by an independent SLIP/CRC decoder. Neither
// direction uses the DUT's own encoder/decoder.
//
// Coverage:
//   * v2 packed frame, little-endian SEQ/LEN/SESSION, escaped payload bytes
//   * CONTROL and business (MIDI/CONFIG) independently queued
//   * business queue full does not block CONTROL reception
//   * bounded queue overflow pulses errors[5], no silent frame loss
//   * CRC, version/type, length, SLIP and inter-byte-timeout errors
//   * flush clears candidate, both queues and TX
//   * generic TX frame with escaping, stable valid/data under backpressure
// -----------------------------------------------------------------------------
module tb_comm_v2_codec;

    localparam logic [7:0] C0 = 8'hC0;
    localparam logic [7:0] DB = 8'hDB;
    localparam logic [7:0] DC = 8'hDC;
    localparam logic [7:0] DD = 8'hDD;

    localparam logic [7:0] TYPE_MIDI    = 8'h01;
    localparam logic [7:0] TYPE_CONFIG  = 8'h02;
    localparam logic [7:0] TYPE_CONTROL = 8'h03;
    localparam logic [7:0] TYPE_REPLY   = 8'h80;
    localparam logic [7:0] TYPE_CTRL_REPLY = 8'h81;

    // Small depths keep the overflow/independence tests short. The timeout is
    // also shortened so a half-frame timeout is observable in simulation.
    localparam int FRAME_DEPTH    = 4;
    localparam int CONTROL_DEPTH  = 2;
    localparam int TIMEOUT_CYCLES = 64;

    logic clk;
    logic rst_n;
    logic flush;

    logic       rx_valid;
    logic       rx_ready;
    logic [7:0] rx_data;

    logic         ctrl_valid;
    logic         ctrl_ready;
    logic [15:0]  ctrl_seq;
    logic [31:0]  ctrl_session;
    logic [5:0]   ctrl_len;
    logic [255:0] ctrl_payload;

    logic         biz_valid;
    logic         biz_ready;
    logic [7:0]   biz_type;
    logic [15:0]  biz_seq;
    logic [31:0]  biz_session;
    logic [5:0]   biz_len;
    logic [255:0] biz_payload;

    logic [7:0] errors;

    logic         send_valid;
    logic         send_ready;
    logic [7:0]   send_type;
    logic [15:0]  send_seq;
    logic [31:0]  send_session;
    logic [5:0]   send_len;
    logic [255:0] send_payload;

    logic       tx_valid;
    logic       tx_ready;
    logic [7:0] tx_data;

    logic [7:0] observed_errors;
    int         fail_count;

    // TX byte capture / TB decoder state.
    logic [7:0] tx_capture [0:255];
    int         tx_count;

    logic [1:0] ready_mode;   // 0=always ready, 1=held low, 2=random
    logic       rnd_ready;

    logic [7:0] tx_held_data;
    logic       tx_held_valid;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    assign tx_ready = (ready_mode == 2'd0) ? 1'b1 :
                      (ready_mode == 2'd1) ? 1'b0 : rnd_ready;

    // -------------------------------------------------------------------------
    // DUT
    // -------------------------------------------------------------------------
    comm_v2_codec #(
        .FRAME_DEPTH(FRAME_DEPTH),
        .CONTROL_DEPTH(CONTROL_DEPTH),
        .TIMEOUT_CYCLES(TIMEOUT_CYCLES)
    ) dut (
        .clk(clk), .rst_n(rst_n), .flush(flush),
        .rx_valid(rx_valid), .rx_ready(rx_ready), .rx_data(rx_data),
        .ctrl_valid(ctrl_valid), .ctrl_ready(ctrl_ready),
        .ctrl_seq(ctrl_seq), .ctrl_session(ctrl_session),
        .ctrl_len(ctrl_len), .ctrl_payload(ctrl_payload),
        .biz_valid(biz_valid), .biz_ready(biz_ready),
        .biz_type(biz_type), .biz_seq(biz_seq), .biz_session(biz_session),
        .biz_len(biz_len), .biz_payload(biz_payload),
        .errors(errors),
        .send_valid(send_valid), .send_ready(send_ready),
        .send_type(send_type), .send_seq(send_seq),
        .send_session(send_session), .send_len(send_len),
        .send_payload(send_payload),
        .tx_valid(tx_valid), .tx_ready(tx_ready), .tx_data(tx_data)
    );

    // Pulse errors are latched here for checking. Sampling on negedge sees the
    // value registered by the preceding posedge.
    always @(negedge clk) begin
        if (rst_n)
            observed_errors = observed_errors | errors;
    end

    always @(posedge clk) begin
        if (rst_n && tx_valid && tx_ready) begin
            tx_capture[tx_count] <= tx_data;
            tx_count <= tx_count + 1;
        end
    end

    always @(negedge clk) begin
        rnd_ready <= $urandom_range(0, 1);
    end

    // -------------------------------------------------------------------------
    // Independent CRC / SLIP helpers (do not call the DUT or comm_pkg)
    // -------------------------------------------------------------------------
    function automatic logic [15:0] tb_crc_byte(
        input logic [15:0] crc, input logic [7:0] data
    );
        logic [15:0] c;
        begin
            c = crc ^ {data, 8'h00};
            for (int i = 0; i < 8; i = i + 1)
                c = c[15] ? ((c << 1) ^ 16'h1021) : (c << 1);
            return c;
        end
    endfunction

    task automatic fail(input string msg);
        begin
            fail_count = fail_count + 1;
            $display("  ERROR: %s (time=%0t)", msg, $time);
        end
    endtask

    task automatic wire_byte(input logic [7:0] b);
        begin
            @(negedge clk);
            rx_valid = 1'b1;
            rx_data  = b;
            @(posedge clk);
            @(negedge clk);
            rx_valid = 1'b0;
        end
    endtask

    // Drive one byte and then leave the line idle for `gap` clocks.  A gap is
    // still well below TIMEOUT_CYCLES; it models a frame split across several
    // UART/FIFO service opportunities rather than a contiguous burst.
    task automatic wire_byte_gap(input logic [7:0] b, input int gap);
        begin
            wire_byte(b);
            repeat (gap) @(posedge clk);
        end
    endtask

    task automatic escaped_out(input logic [7:0] b);
        begin
            if (b == C0) begin
                wire_byte(DB);
                wire_byte(DC);
            end else if (b == DB) begin
                wire_byte(DB);
                wire_byte(DD);
            end else begin
                wire_byte(b);
            end
        end
    endtask

    task automatic escaped_out_gap(input logic [7:0] b, input int gap);
        begin
            if (b == C0) begin
                wire_byte_gap(DB, gap);
                wire_byte_gap(DC, gap);
            end else if (b == DB) begin
                wire_byte_gap(DB, gap);
                wire_byte_gap(DD, gap);
            end else begin
                wire_byte_gap(b, gap);
            end
        end
    endtask

    // Emit a complete v2 body (without SLIP delimiters).  Keeping this separate
    // lets the shared-delimiter test emit two bodies around one C0.
    task automatic wire_body(
        input logic [7:0]   typ,
        input logic [15:0]  seq,
        input logic [31:0]  session,
        input logic [5:0]   len,
        input logic [255:0] payload,
        input bit           corrupt_crc,
        input int           gap
    );
        logic [7:0]  body [0:63];
        logic [15:0] crc;
        int          i;
        int          total;
        begin
            body[0] = 8'h02;
            body[1] = typ;
            body[2] = seq[7:0];
            body[3] = seq[15:8];
            body[4] = {2'b00, len};
            body[5] = 8'h00;
            for (i = 0; i < 4; i = i + 1)
                body[6+i] = session[i*8 +: 8];
            for (i = 0; i < len; i = i + 1)
                body[10+i] = (i < 32) ? payload[i*8 +: 8] : 8'h00;

            crc = 16'hFFFF;
            for (i = 0; i < (10 + len); i = i + 1)
                crc = tb_crc_byte(crc, body[i]);
            if (corrupt_crc)
                crc = crc ^ 16'h0001;

            body[10+len] = crc[7:0];
            body[11+len] = crc[15:8];
            total = 12 + len;

            for (i = 0; i < total; i = i + 1) begin
                if (gap == 0)
                    escaped_out(body[i]);
                else
                    escaped_out_gap(body[i], gap);
            end
        end
    endtask

    // Build a complete v2 frame and drive it on the raw RX interface.
    task automatic send_frame(
        input logic [7:0]   typ,
        input logic [15:0]  seq,
        input logic [31:0]  session,
        input logic [5:0]   len,
        input logic [255:0] payload,
        input bit           corrupt_crc
    );
        begin
            wire_byte(C0);
            wire_body(typ, seq, session, len, payload, corrupt_crc, 0);
            wire_byte(C0);
        end
    endtask

    // -------------------------------------------------------------------------
    // Queue checks
    // -------------------------------------------------------------------------
    task automatic expect_ctrl(
        input logic [15:0]  seq,
        input logic [31:0]  session,
        input logic [5:0]   len,
        input logic [255:0] payload,
        input string        label
    );
        int guard;
        int i;
        begin
            guard = 0;
            while (!ctrl_valid) begin
                @(posedge clk);
                guard = guard + 1;
                if (guard > 20000) begin
                    fail({label, ": ctrl_valid timeout"});
                    disable expect_ctrl;
                end
            end

            if (ctrl_seq !== seq) begin
                $display("    ctrl_seq got=%04x exp=%04x", ctrl_seq, seq);
                fail({label, ": ctrl_seq"});
            end
            if (ctrl_session !== session) begin
                $display("    ctrl_session got=%08x exp=%08x", ctrl_session, session);
                fail({label, ": ctrl_session"});
            end
            if (ctrl_len !== len) begin
                $display("    ctrl_len got=%0d exp=%0d", ctrl_len, len);
                fail({label, ": ctrl_len"});
            end
            for (i = 0; i < len; i = i + 1) begin
                if (ctrl_payload[i*8 +: 8] !== payload[i*8 +: 8]) begin
                    $display("    ctrl_payload[%0d] got=%02x exp=%02x",
                             i, ctrl_payload[i*8 +: 8], payload[i*8 +: 8]);
                    fail({label, ": ctrl_payload"});
                end
            end

            @(negedge clk);
            ctrl_ready = 1'b1;
            @(posedge clk);
            @(negedge clk);
            ctrl_ready = 1'b0;
        end
    endtask

    task automatic expect_biz(
        input logic [7:0]   typ,
        input logic [15:0]  seq,
        input logic [31:0]  session,
        input logic [5:0]   len,
        input logic [255:0] payload,
        input string        label
    );
        int guard;
        int i;
        begin
            guard = 0;
            while (!biz_valid) begin
                @(posedge clk);
                guard = guard + 1;
                if (guard > 20000) begin
                    fail({label, ": biz_valid timeout"});
                    disable expect_biz;
                end
            end

            if (biz_type !== typ) begin
                $display("    biz_type got=%02x exp=%02x", biz_type, typ);
                fail({label, ": biz_type"});
            end
            if (biz_seq !== seq) begin
                $display("    biz_seq got=%04x exp=%04x", biz_seq, seq);
                fail({label, ": biz_seq"});
            end
            if (biz_session !== session) begin
                $display("    biz_session got=%08x exp=%08x", biz_session, session);
                fail({label, ": biz_session"});
            end
            if (biz_len !== len) begin
                $display("    biz_len got=%0d exp=%0d", biz_len, len);
                fail({label, ": biz_len"});
            end
            for (i = 0; i < len; i = i + 1) begin
                if (biz_payload[i*8 +: 8] !== payload[i*8 +: 8]) begin
                    $display("    biz_payload[%0d] got=%02x exp=%02x",
                             i, biz_payload[i*8 +: 8], payload[i*8 +: 8]);
                    fail({label, ": biz_payload"});
                end
            end

            @(negedge clk);
            biz_ready = 1'b1;
            @(posedge clk);
            @(negedge clk);
            biz_ready = 1'b0;
        end
    endtask

    task automatic clear_observed;
        begin
            @(negedge clk);
            observed_errors = 8'h00;
        end
    endtask

    task automatic expect_error_exact(input int err_bit, input string label);
        int guard;
        logic [7:0] others;
        begin
            guard = 0;
            while (((observed_errors >> err_bit) & 8'h01) == 8'h00) begin
                @(negedge clk);
                guard = guard + 1;
                if (guard > 30000) begin
                    $display("    observed_errors=%02x", observed_errors);
                    fail({label, ": expected error bit not seen"});
                    disable expect_error_exact;
                end
            end
            others = observed_errors & ~(8'h01 << err_bit);
            if (others != 8'h00) begin
                $display("    observed_errors=%02x extra bits for %s", observed_errors, label);
                fail({label, ": unexpected extra error bits"});
            end
            observed_errors[err_bit] = 1'b0;
        end
    endtask

    task automatic expect_no_frame(input string label);
        begin
            repeat (3) @(negedge clk);
            if (ctrl_valid || biz_valid)
                fail({label, ": unexpected valid frame"});
        end
    endtask

    // -------------------------------------------------------------------------
    // TX descriptor / decoder checks
    // -------------------------------------------------------------------------
    task automatic send_descriptor(
        input logic [7:0]   typ,
        input logic [15:0]  seq,
        input logic [31:0]  session,
        input logic [5:0]   len,
        input logic [255:0] payload
    );
        begin
            @(negedge clk);
            send_valid   = 1'b1;
            send_type    = typ;
            send_seq     = seq;
            send_session = session;
            send_len     = len;
            send_payload = payload;
            while (!send_ready)
                @(negedge clk);
            @(posedge clk);
            @(negedge clk);
            send_valid = 1'b0;
        end
    endtask

    task automatic wait_tx_done(input string label);
        int guard;
        begin
            guard = 0;
            while (!tx_valid) begin
                @(posedge clk);
                guard = guard + 1;
                if (guard > 20000) begin
                    fail({label, ": tx_valid timeout"});
                    disable wait_tx_done;
                end
            end
            while (tx_valid) begin
                @(posedge clk);
                guard = guard + 1;
                if (guard > 20000) begin
                    fail({label, ": TX did not finish"});
                    disable wait_tx_done;
                end
            end
            repeat (3) @(posedge clk);
        end
    endtask

    // Independent streaming SLIP decoder for the captured TX bytes.  It strips
    // escapes, checks the delimiter/CRC rules, then reconstructs every header
    // field with the inverse of the wire little-endian layout.  It does not
    // call any DUT function or the comm_pkg CRC helper.
    task automatic decode_tx(
        input logic [7:0]   typ,
        input logic [15:0]  seq,
        input logic [31:0]  session,
        input logic [5:0]   len,
        input logic [255:0] payload,
        input string        label
    );
        logic [7:0]  body [0:63];
        logic [7:0]  b;
        logic [15:0] crc;
        int          idx;
        int          n;
        int          i;
        begin
            if (tx_count < 14) begin
                fail({label, ": TX decoder short capture"});
                disable decode_tx;
            end
            if (tx_capture[0] !== C0) begin
                fail({label, ": TX decoder missing lead C0"});
                disable decode_tx;
            end

            idx = 1;
            n   = 0;
            while ((idx < tx_count) && (tx_capture[idx] !== C0)) begin
                b = tx_capture[idx];
                if (b == DB) begin
                    idx = idx + 1;
                    if (idx >= tx_count) begin
                        fail({label, ": TX decoder dangling escape"});
                        disable decode_tx;
                    end
                    b = tx_capture[idx];
                    if (b == DC)
                        b = C0;
                    else if (b == DD)
                        b = DB;
                    else begin
                        $display("    TX decoder bad escape DB %02x", b);
                        fail({label, ": TX decoder bad escape"});
                        disable decode_tx;
                    end
                end
                if (n >= 64) begin
                    fail({label, ": TX decoder overlong body"});
                    disable decode_tx;
                end
                body[n] = b;
                n       = n + 1;
                idx     = idx + 1;
            end

            if (idx >= tx_count) begin
                fail({label, ": TX decoder missing tail C0"});
                disable decode_tx;
            end
            if (tx_capture[idx] !== C0)
                fail({label, ": TX decoder tail is not C0"});
            if (idx != (tx_count - 1))
                fail({label, ": TX decoder bytes after tail C0"});
            if (n != (12 + len)) begin
                $display("    TX decoder body got=%0d exp=%0d", n, 12 + len);
                fail({label, ": TX decoder body length"});
                disable decode_tx;
            end

            if (body[0] !== 8'h02)
                fail({label, ": TX decoder version"});
            if (body[1] !== typ)
                fail({label, ": TX decoder type"});
            if ({body[3], body[2]} !== seq)
                fail({label, ": TX decoder seq endian"});
            if ((body[4] !== {2'b00, len}) || (body[5] !== 8'h00))
                fail({label, ": TX decoder len endian"});
            for (i = 0; i < 4; i = i + 1)
                if (body[6+i] !== session[i*8 +: 8])
                    fail({label, ": TX decoder session endian"});
            for (i = 0; i < len; i = i + 1)
                if (body[10+i] !== payload[i*8 +: 8])
                    fail({label, ": TX decoder payload"});

            crc = 16'hFFFF;
            for (i = 0; i < (10 + len); i = i + 1)
                crc = tb_crc_byte(crc, body[i]);
            if ({body[11+len], body[10+len]} !== crc) begin
                $display("    TX decoder crc got=%04x exp=%04x",
                         {body[11+len], body[10+len]}, crc);
                fail({label, ": TX decoder CRC"});
            end
        end
    endtask

    task automatic check_tx(
        input logic [7:0]   typ,
        input logic [15:0]  seq,
        input logic [31:0]  session,
        input logic [5:0]   len,
        input logic [255:0] payload,
        input string        label
    );
        logic [7:0]  body [0:63];
        logic [7:0]  exp  [0:255];
        logic [15:0] crc;
        int          i;
        int          n;
        int          en;
        begin
            decode_tx(typ, seq, session, len, payload, label);

            body[0] = 8'h02;
            body[1] = typ;
            body[2] = seq[7:0];
            body[3] = seq[15:8];
            body[4] = {2'b00, len};
            body[5] = 8'h00;
            for (i = 0; i < 4; i = i + 1)
                body[6+i] = session[i*8 +: 8];
            for (i = 0; i < len; i = i + 1)
                body[10+i] = payload[i*8 +: 8];

            crc = 16'hFFFF;
            for (i = 0; i < (10 + len); i = i + 1)
                crc = tb_crc_byte(crc, body[i]);
            body[10+len] = crc[7:0];
            body[11+len] = crc[15:8];
            n = 12 + len;

            exp[0] = C0;
            en = 1;
            for (i = 0; i < n; i = i + 1) begin
                if (body[i] == C0) begin
                    exp[en] = DB;
                    exp[en+1] = DC;
                    en = en + 2;
                end else if (body[i] == DB) begin
                    exp[en] = DB;
                    exp[en+1] = DD;
                    en = en + 2;
                end else begin
                    exp[en] = body[i];
                    en = en + 1;
                end
            end
            exp[en] = C0;
            en = en + 1;

            if (tx_count != en) begin
                $display("    TX bytes got=%0d exp=%0d", tx_count, en);
                fail({label, ": TX length"});
            end
            for (i = 0; i < en && i < tx_count; i = i + 1) begin
                if (tx_capture[i] !== exp[i]) begin
                    $display("    TX[%0d] got=%02x exp=%02x", i, tx_capture[i], exp[i]);
                    fail({label, ": TX byte/escape/CRC"});
                end
            end
        end
    endtask

    // -------------------------------------------------------------------------
    // Main sequence
    // -------------------------------------------------------------------------
    logic [255:0] p;
    logic [255:0] p2;
    int           i;
    int           n;
    logic [15:0]  seq;
    logic [31:0]  sess;
    logic [7:0]   saved_tx_data;
    logic [15:0]  crc_self;

    initial begin
        fail_count      = 0;
        rst_n           = 1'b0;
        flush           = 1'b0;
        rx_valid        = 1'b0;
        rx_data         = 8'h00;
        ctrl_ready      = 1'b0;
        biz_ready       = 1'b0;
        send_valid      = 1'b0;
        send_type       = 8'h00;
        send_seq        = 16'h0000;
        send_session    = 32'h00000000;
        send_len        = 6'd0;
        send_payload    = 256'd0;
        ready_mode      = 2'd0;
        rnd_ready       = 1'b1;
        observed_errors = 8'h00;
        tx_count        = 0;
        tx_held_data    = 8'h00;
        tx_held_valid   = 1'b0;

        repeat (4) @(posedge clk);
        @(negedge clk);
        rst_n = 1'b1;
        repeat (3) @(posedge clk);
        $display("=== tb_comm_v2_codec start ===");
        if (observed_errors != 8'h00)
            fail("error pulse during reset");

        // Prove the testbench CRC model is standard CRC-16/CCITT-FALSE: the
        // check value of "123456789" is 0x29B1.
        crc_self = 16'hFFFF;
        crc_self = tb_crc_byte(crc_self, 8'h31);
        crc_self = tb_crc_byte(crc_self, 8'h32);
        crc_self = tb_crc_byte(crc_self, 8'h33);
        crc_self = tb_crc_byte(crc_self, 8'h34);
        crc_self = tb_crc_byte(crc_self, 8'h35);
        crc_self = tb_crc_byte(crc_self, 8'h36);
        crc_self = tb_crc_byte(crc_self, 8'h37);
        crc_self = tb_crc_byte(crc_self, 8'h38);
        crc_self = tb_crc_byte(crc_self, 8'h39);
        if (crc_self !== 16'h29B1) begin
            $display("    TB CRC self-check got=%04x exp=29B1", crc_self);
            fail("testbench CRC model");
        end

        // ---------------------------------------------------------------------
        // 1. CONTROL frame: little-endian fields + escaped payload
        // ---------------------------------------------------------------------
        $display("[1] CONTROL RX, little-endian fields, escaped payload");
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h01;   // HELLO
        p[1*8 +: 8] = C0;      // must be escaped on the wire
        p[2*8 +: 8] = DB;      // must be escaped on the wire
        p[3*8 +: 8] = 8'h34;
        p[4*8 +: 8] = 8'h12;
        send_frame(TYPE_CONTROL, 16'h1234, 32'h89ABCDEF, 6'd5, p, 1'b0);
        expect_ctrl(16'h1234, 32'h89ABCDEF, 6'd5, p, "control escaped");
        expect_no_frame("control escaped");
        if (observed_errors != 8'h00)
            fail("control escaped: unexpected error");

        // ---------------------------------------------------------------------
        // 1b. Shared delimiter, fragmented bytes, empty frames
        // ---------------------------------------------------------------------
        $display("[1b] Shared C0 delimiter, fragmented byte timing, empty frames");
        clear_observed;
        p  = 256'd0;
        p2 = 256'd0;
        p[0*8 +: 8]  = 8'h05;   // RESUME-like control payload
        p[1*8 +: 8]  = 8'hC0;
        p2[0*8 +: 8] = 8'h34;
        p2[1*8 +: 8] = 8'h12;
        p2[2*8 +: 8] = 8'h90;
        p2[3*8 +: 8] = 8'h3C;

        // Two complete frames with exactly one C0 between them:
        //   C0 body_A C0 body_B C0
        // The middle C0 is both body_A's tail and body_B's lead.
        wire_byte(C0);
        wire_body(TYPE_CONTROL, 16'hA1A1, 32'hA1A1A1A1, 6'd2, p, 1'b0, 0);
        wire_byte(C0);
        wire_body(TYPE_MIDI, 16'hA2A2, 32'hA2A2A2A2, 6'd4, p2, 1'b0, 0);
        wire_byte(C0);
        expect_ctrl(16'hA1A1, 32'hA1A1A1A1, 6'd2, p, "shared delimiter ctrl");
        expect_biz(TYPE_MIDI, 16'hA2A2, 32'hA2A2A2A2, 6'd4, p2,
                   "shared delimiter biz");
        expect_no_frame("shared delimiter");
        if (observed_errors != 8'h00)
            fail("shared delimiter: unexpected error");

        // A frame whose bytes are separated by idle clocks (still below the
        // inter-byte timeout) must decode exactly like a contiguous burst.
        clear_observed;
        wire_byte(C0);
        wire_body(TYPE_CONTROL, 16'hA3A3, 32'hA3A3A3A3, 6'd2, p, 1'b0, 2);
        wire_byte(C0);
        expect_ctrl(16'hA3A3, 32'hA3A3A3A3, 6'd2, p, "fragmented ctrl");
        expect_no_frame("fragmented ctrl");
        if (observed_errors != 8'h00)
            fail("fragmented ctrl: unexpected error");

        // Repeated empty delimiters are legal idle fill and must not produce a
        // frame or an error.  A subsequent frame must still start cleanly.
        clear_observed;
        repeat (3) wire_byte(C0);
        send_frame(TYPE_CONTROL, 16'hA4A4, 32'hA4A4A4A4, 6'd2, p, 1'b0);
        expect_ctrl(16'hA4A4, 32'hA4A4A4A4, 6'd2, p, "empty-fill resync");
        expect_no_frame("empty-fill resync");
        if (observed_errors != 8'h00)
            fail("empty-fill resync: unexpected error");

        // ---------------------------------------------------------------------
        // 2. Business frames: MIDI, CONFIG, max-length MIDI
        // ---------------------------------------------------------------------
        $display("[2] MIDI / CONFIG RX and max payload");
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h34;   // epoch LSB
        p[1*8 +: 8] = 8'h12;   // epoch MSB
        p[2*8 +: 8] = 8'h90;   // MIDI status
        p[3*8 +: 8] = 8'h3C;   // note
        send_frame(TYPE_MIDI, 16'h0007, 32'h01020304, 6'd4, p, 1'b0);
        expect_biz(TYPE_MIDI, 16'h0007, 32'h01020304, 6'd4, p, "midi");

        p = 256'd0;
        for (i = 0; i < 16; i = i + 1)
            p[i*8 +: 8] = 8'hA0 + i[7:0];
        p[0*8 +: 8] = C0;      // exercise escaping inside a CONFIG payload
        p[1*8 +: 8] = DB;
        send_frame(TYPE_CONFIG, 16'hBEEF, 32'hCAFEBABE, 6'd16, p, 1'b0);
        expect_biz(TYPE_CONFIG, 16'hBEEF, 32'hCAFEBABE, 6'd16, p, "config16");

        p = 256'd0;
        for (i = 0; i < 32; i = i + 1)
            p[i*8 +: 8] = 8'h30 + i[7:0];
        p[0*8 +: 8] = 8'hC0;
        p[5*8 +: 8] = 8'hDB;
        p[31*8 +: 8] = 8'hC0;
        send_frame(TYPE_MIDI, 16'hFFFE, 32'h7FFFFFFF, 6'd32, p, 1'b0);
        expect_biz(TYPE_MIDI, 16'hFFFE, 32'h7FFFFFFF, 6'd32, p, "midi32");
        if (observed_errors != 8'h00)
            fail("business RX: unexpected error");

        // ---------------------------------------------------------------------
        // 3. Independent queues and bounded overflow
        // ---------------------------------------------------------------------
        $display("[3] Independent CONTROL/BIZ queues and overflow");
        clear_observed;
        for (i = 0; i < FRAME_DEPTH; i = i + 1) begin
            p = 256'd0;
            p[0*8 +: 8] = i[7:0];
            p[1*8 +: 8] = 8'h11;
            p[2*8 +: 8] = 8'h22;
            send_frame(TYPE_MIDI, 16'h0100 + i[15:0], 32'h11110000 + i[31:0],
                       6'd3, p, 1'b0);
        end
        if (observed_errors != 8'h00)
            fail("queue fill: unexpected error");

        // Business queue is now full. CONTROL must still be accepted.
        for (i = 0; i < CONTROL_DEPTH; i = i + 1) begin
            p = 256'd0;
            p[0*8 +: 8] = 8'h03;
            p[1*8 +: 8] = i[7:0];
            send_frame(TYPE_CONTROL, 16'h2000 + i[15:0], 32'hAAAA0000 + i[31:0],
                       6'd2, p, 1'b0);
        end
        if (observed_errors != 8'h00)
            fail("control while biz full: unexpected error");
        if (!biz_valid)
            fail("biz queue should be full/valid");
        if (!ctrl_valid)
            fail("ctrl queue should hold frames while biz full");

        // CONTROL queue full -> overflow bit 5.
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h03;
        send_frame(TYPE_CONTROL, 16'h2003, 32'hAAAA0003, 6'd1, p, 1'b0);
        expect_error_exact(5, "control overflow");

        // Business queue full -> overflow bit 5.
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h01;
        send_frame(TYPE_MIDI, 16'h0200, 32'h22220000, 6'd3, p, 1'b0);
        expect_error_exact(5, "biz overflow");

        // Drain in FIFO order and confirm no earlier frame was corrupted.
        for (i = 0; i < CONTROL_DEPTH; i = i + 1) begin
            p = 256'd0;
            p[0*8 +: 8] = 8'h03;
            p[1*8 +: 8] = i[7:0];
            expect_ctrl(16'h2000 + i[15:0], 32'hAAAA0000 + i[31:0], 6'd2, p,
                        "ctrl drain");
        end
        for (i = 0; i < FRAME_DEPTH; i = i + 1) begin
            p = 256'd0;
            p[0*8 +: 8] = i[7:0];
            p[1*8 +: 8] = 8'h11;
            p[2*8 +: 8] = 8'h22;
            expect_biz(TYPE_MIDI, 16'h0100 + i[15:0], 32'h11110000 + i[31:0],
                       6'd3, p, "biz drain");
        end
        expect_no_frame("queue drain: overflow frame was not enqueued");

        // Both queues must recover after the overflow.
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h04;
        send_frame(TYPE_CONTROL, 16'h2004, 32'hAAAA0004, 6'd1, p, 1'b0);
        expect_ctrl(16'h2004, 32'hAAAA0004, 6'd1, p, "ctrl recovery");
        p = 256'd0;
        p[0*8 +: 8] = 8'h05;
        p[1*8 +: 8] = 8'h05;
        p[2*8 +: 8] = 8'h05;
        send_frame(TYPE_MIDI, 16'h0201, 32'h22220001, 6'd3, p, 1'b0);
        expect_biz(TYPE_MIDI, 16'h0201, 32'h22220001, 6'd3, p, "biz recovery");
        if (observed_errors != 8'h00)
            fail("queue recovery: unexpected error");

        // ---------------------------------------------------------------------
        // 4. CRC and malformed frames
        // ---------------------------------------------------------------------
        $display("[4] CRC / header / length / SLIP malformed frames");

        // CRC error.
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h01;
        send_frame(TYPE_CONTROL, 16'h3001, 32'h33330001, 6'd1, p, 1'b1);
        expect_error_exact(2, "bad CRC");
        expect_no_frame("bad CRC");

        // Wrong version byte.
        clear_observed;
        wire_byte(C0);
        wire_byte(8'h03);   // bad version
        wire_byte(TYPE_CONTROL);
        wire_byte(8'h00); wire_byte(8'h00);
        wire_byte(8'h01); wire_byte(8'h00);
        wire_byte(8'h00); wire_byte(8'h00);
        wire_byte(8'h00); wire_byte(8'h00);
        wire_byte(C0);
        expect_error_exact(3, "bad version");
        expect_no_frame("bad version");

        // Wrong type (reply is TX-only on the device RX path).
        clear_observed;
        wire_byte(C0);
        wire_byte(8'h02);
        wire_byte(TYPE_REPLY);
        wire_byte(8'h00); wire_byte(8'h00);
        wire_byte(8'h01); wire_byte(8'h00);
        wire_byte(8'h00); wire_byte(8'h00);
        wire_byte(8'h00); wire_byte(8'h00);
        wire_byte(C0);
        expect_error_exact(3, "bad type");
        expect_no_frame("bad type");

        // LEN = 0.
        clear_observed;
        p = 256'd0;
        send_frame(TYPE_CONTROL, 16'h3004, 32'h33330004, 6'd0, p, 1'b0);
        expect_error_exact(1, "len zero");
        expect_no_frame("len zero");

        // LEN = 33 (> 32).
        clear_observed;
        p = 256'd0;
        send_frame(TYPE_MIDI, 16'h3005, 32'h33330005, 6'd33, p, 1'b0);
        expect_error_exact(1, "len 33");
        expect_no_frame("len 33");

        // LEN is u16 little-endian: a nonzero high byte (0x0103 = 259) must be
        // rejected by the full 16-bit length check, not truncated to 0x03.
        clear_observed;
        wire_byte(C0);
        wire_byte(8'h02);
        wire_byte(TYPE_MIDI);
        wire_byte(8'h34); wire_byte(8'h12);   // SEQ
        wire_byte(8'h03); wire_byte(8'h01);   // LEN = 0x0103
        wire_byte(8'h78); wire_byte(8'h56);
        wire_byte(8'h34); wire_byte(8'h12);   // SESSION
        wire_byte(8'h90); wire_byte(8'h3C); wire_byte(8'h40);
        wire_byte(8'h00); wire_byte(8'h00);   // would-be CRC
        wire_byte(C0);
        expect_error_exact(1, "len high byte");
        expect_no_frame("len high byte");

        // CONFIG LEN = 17 (> 16).
        clear_observed;
        p = 256'd0;
        send_frame(TYPE_CONFIG, 16'h3006, 32'h33330006, 6'd17, p, 1'b0);
        expect_error_exact(1, "config len 17");
        expect_no_frame("config len 17");

        // MIDI LEN = 2 (< epoch + one MIDI byte).
        clear_observed;
        p = 256'd0;
        send_frame(TYPE_MIDI, 16'h3007, 32'h33330007, 6'd2, p, 1'b0);
        expect_error_exact(1, "midi len 2");
        expect_no_frame("midi len 2");

        // Illegal SLIP escape DB 00.
        clear_observed;
        wire_byte(C0);
        wire_byte(8'h02);
        wire_byte(TYPE_CONTROL);
        wire_byte(DB);
        wire_byte(8'h00);
        wire_byte(C0);
        expect_error_exact(0, "bad SLIP escape");
        expect_no_frame("bad SLIP escape");

        // Truncated body (missing CRC) still terminated by C0.
        clear_observed;
        wire_byte(C0);
        wire_byte(8'h02);
        wire_byte(TYPE_CONTROL);
        wire_byte(8'h00); wire_byte(8'h00);
        wire_byte(8'h05); wire_byte(8'h00);
        wire_byte(8'h01);
        wire_byte(C0);
        expect_error_exact(1, "truncated body");
        expect_no_frame("truncated body");

        // A good frame immediately after all malformed traffic must work.
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h7E;
        send_frame(TYPE_CONTROL, 16'h3008, 32'h33330008, 6'd1, p, 1'b0);
        expect_ctrl(16'h3008, 32'h33330008, 6'd1, p, "post-malformed recovery");
        if (observed_errors != 8'h00)
            fail("post-malformed recovery: unexpected error");

        // ---------------------------------------------------------------------
        // 5. Inter-byte timeout
        // ---------------------------------------------------------------------
        $display("[5] Inter-byte timeout on a half frame");
        clear_observed;
        wire_byte(C0);
        wire_byte(8'h02);
        wire_byte(TYPE_CONTROL);
        wire_byte(8'h00);
        wire_byte(8'h00);
        wire_byte(8'h05);
        wire_byte(8'h00);
        repeat (TIMEOUT_CYCLES + 20) @(posedge clk);
        expect_error_exact(4, "timeout");
        expect_no_frame("timeout");

        // Timeout must leave the decoder able to resynchronize on a new C0.
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h55;
        send_frame(TYPE_CONTROL, 16'h3009, 32'h33330009, 6'd1, p, 1'b0);
        expect_ctrl(16'h3009, 32'h33330009, 6'd1, p, "post-timeout recovery");
        if (observed_errors != 8'h00)
            fail("post-timeout recovery: unexpected error");

        // Idle line time is not a half frame: waiting several timeout periods
        // with no candidate started must not raise the inter-byte timeout.
        clear_observed;
        repeat (TIMEOUT_CYCLES + 20) @(posedge clk);
        @(negedge clk);
        if (observed_errors != 8'h00)
            fail("idle line incorrectly timed out");

        // ---------------------------------------------------------------------
        // 6. Flush clears candidate, queues and TX
        // ---------------------------------------------------------------------
        $display("[6] Flush clears candidate / queues / TX");
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h01;
        send_frame(TYPE_CONTROL, 16'h4001, 32'h44440001, 6'd1, p, 1'b0);
        send_frame(TYPE_MIDI, 16'h4002, 32'h44440002, 6'd3, p, 1'b0);
        // Leave a half-decoded candidate too.
        wire_byte(C0);
        wire_byte(8'h02);
        wire_byte(TYPE_CONTROL);

        // Start a TX frame and hold the byte output so it is active.
        ready_mode = 2'd1;
        send_descriptor(TYPE_REPLY, 16'h4003, 32'h44440003, 6'd3,
                        {8'h02, 8'h03, 8'h04});
        wait (tx_valid === 1'b1);

        @(negedge clk);
        flush = 1'b1;
        @(posedge clk);
        @(negedge clk);
        flush = 1'b0;
        repeat (3) @(negedge clk);

        if (ctrl_valid || biz_valid)
            fail("flush did not clear queues");
        if (tx_valid)
            fail("flush did not clear TX");
        if (observed_errors != 8'h00)
            fail("flush: unexpected error");

        // New traffic after flush, including TX, must work.
        ready_mode = 2'd0;
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = 8'h66;
        send_frame(TYPE_CONTROL, 16'h4004, 32'h44440004, 6'd1, p, 1'b0);
        expect_ctrl(16'h4004, 32'h44440004, 6'd1, p, "post-flush RX");
        if (observed_errors != 8'h00)
            fail("post-flush RX: unexpected error");

        @(negedge clk);
        tx_count = 0;
        send_descriptor(TYPE_MIDI, 16'h4005, 32'h44440005, 6'd4,
                        {8'h00, 8'h00, 8'h90, 8'h3C});
        wait_tx_done("post-flush TX");
        check_tx(TYPE_MIDI, 16'h4005, 32'h44440005, 6'd4,
                 {8'h00, 8'h00, 8'h90, 8'h3C}, "post-flush TX");

        // ---------------------------------------------------------------------
        // 7. TX generic frames, escaping and backpressure
        // ---------------------------------------------------------------------
        $display("[7] TX generic frame, escaping, stable backpressure");

        // Escapes in SEQ, SESSION and payload, plus a CRC byte that needs it.
        clear_observed;
        p = 256'd0;
        p[0*8 +: 8] = C0;
        p[1*8 +: 8] = DB;
        p[2*8 +: 8] = 8'h00;
        p[3*8 +: 8] = 8'hFF;
        p[4*8 +: 8] = C0;
        p[5*8 +: 8] = DB;
        p[6*8 +: 8] = 8'h5A;
        p[7*8 +: 8] = 8'h4E;   // makes CRC high byte DB, forcing escape
        @(negedge clk);
        tx_count = 0;
        ready_mode = 2'd0;
        send_descriptor(TYPE_CTRL_REPLY, 16'h00C0, 32'hDB11C0DD, 6'd8, p);
        wait_tx_done("TX escaped frame");
        check_tx(TYPE_CTRL_REPLY, 16'h00C0, 32'hDB11C0DD, 6'd8, p,
                 "TX escaped frame");
        if (observed_errors != 8'h00)
            fail("TX escaped frame: unexpected RX error");

        // Hold tx_ready low and verify tx_valid/data are stable.
        p = 256'd0;
        p[0*8 +: 8] = 8'h02;
        p[1*8 +: 8] = C0;
        p[2*8 +: 8] = DB;
        @(negedge clk);
        tx_count = 0;
        ready_mode = 2'd1;
        send_descriptor(TYPE_REPLY, 16'h3412, 32'h0000C0DB, 6'd3, p);
        wait (tx_valid === 1'b1);
        @(negedge clk);
        saved_tx_data = tx_data;
        for (i = 0; i < 20; i = i + 1) begin
            @(posedge clk);
            if (!tx_valid)
                fail("TX valid dropped while tx_ready low");
            if (tx_data !== saved_tx_data)
                fail("TX data changed while tx_ready low");
            if (send_ready)
                fail("send_ready asserted while TX busy");
        end
        ready_mode = 2'd2;   // random backpressure for the rest of the frame
        wait_tx_done("TX backpressure frame");
        check_tx(TYPE_REPLY, 16'h3412, 32'h0000C0DB, 6'd3, p,
                 "TX backpressure frame");

        // Max-length generic frame under random backpressure.
        p = 256'd0;
        for (i = 0; i < 32; i = i + 1)
            p[i*8 +: 8] = (i == 0) ? C0 :
                          (i == 7) ? DB :
                          (i == 15) ? C0 :
                          (i == 23) ? DB : (8'h80 + i[7:0]);
        @(negedge clk);
        tx_count = 0;
        ready_mode = 2'd2;
        send_descriptor(TYPE_CONTROL, 16'hC0DB, 32'hDDCCBBAA, 6'd32, p);
        wait_tx_done("TX max frame");
        check_tx(TYPE_CONTROL, 16'hC0DB, 32'hDDCCBBAA, 6'd32, p,
                 "TX max frame");

        // Escape-heavy max frame: every payload byte and most header bytes need
        // DB/DC or DB/DD expansion.  This is the long-wire/backpressure case.
        p = 256'd0;
        for (i = 0; i < 32; i = i + 1)
            p[i*8 +: 8] = i[0] ? DB : C0;
        @(negedge clk);
        tx_count = 0;
        ready_mode = 2'd2;
        send_descriptor(8'hDB, 16'hC0DB, 32'hDB00C0DD, 6'd32, p);
        wait_tx_done("TX escape-heavy frame");
        check_tx(8'hDB, 16'hC0DB, 32'hDB00C0DD, 6'd32, p,
                 "TX escape-heavy frame");

        if (observed_errors != 8'h00)
            fail("TX tests: unexpected RX error");

        // ---------------------------------------------------------------------
        // Summary
        // ---------------------------------------------------------------------
        repeat (3) @(posedge clk);
        if (fail_count == 0)
            $display("PASS: comm_v2_codec (RX queues/errors + TX framing)");
        else
            $display("FAIL: comm_v2_codec had %0d error(s)", fail_count);
        $finish;
    end

    // Safety timeout.
    initial begin
        #5_000_000;
        $display("FAIL: simulation wall-clock timeout");
        $finish;
    end

endmodule
